-- ---------------------------------------------------------------------------------------------
-- Constraints Prisma cannot express (Backend Schema 4)
-- ---------------------------------------------------------------------------------------------
ALTER TABLE public.organizations
  ADD CONSTRAINT organizations_name_length CHECK (char_length(name) BETWEEN 2 AND 120),
  ADD CONSTRAINT organizations_slug_format CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  ADD CONSTRAINT organizations_primary_color_format CHECK (primary_color ~ '^#[0-9A-F]{6}$'),
  ADD CONSTRAINT organizations_sms_sender_id_length CHECK (char_length(sms_sender_id) <= 11),
  ADD CONSTRAINT organizations_session_timeout_range CHECK (session_timeout_minutes BETWEEN 5 AND 60),
  ADD CONSTRAINT organizations_archive_after_days_positive CHECK (archive_after_days > 0);

ALTER TABLE public.users
  ADD CONSTRAINT users_platform_admin_has_no_org CHECK (is_platform_admin = (organization_id IS NULL)),
  ADD CONSTRAINT users_super_admin_has_org CHECK (NOT (is_org_super_admin AND organization_id IS NULL)),
  ADD CONSTRAINT users_language_values CHECK (language IN ('sw', 'en')),
  ADD CONSTRAINT users_theme_preference_values CHECK (theme_preference IN ('system', 'light', 'dark')),
  ADD CONSTRAINT users_failed_login_count_non_negative CHECK (failed_login_count >= 0);

ALTER TABLE public.user_tokens
  ADD CONSTRAINT user_tokens_purpose_values CHECK (purpose IN ('invite', 'password_reset'));

ALTER TABLE public.permissions
  ADD CONSTRAINT permissions_scope_values CHECK (scope IN ('org', 'event', 'platform'));

ALTER TABLE public.roles
  ADD CONSTRAINT roles_system_key_values
    CHECK (system_key IN ('org_super_admin', 'admin', 'moderator', 'observer')),
  ADD CONSTRAINT roles_is_system_matches_key CHECK (is_system = (system_key IS NOT NULL)),
  ADD CONSTRAINT roles_name_length CHECK (char_length(name) BETWEEN 1 AND 80);

-- ---------------------------------------------------------------------------------------------
-- updated_at (Backend Schema 1.2)
-- ---------------------------------------------------------------------------------------------
CREATE TRIGGER organizations_updated_at BEFORE UPDATE ON public.organizations
  FOR EACH ROW EXECUTE FUNCTION app.set_updated_at();
CREATE TRIGGER users_updated_at BEFORE UPDATE ON public.users
  FOR EACH ROW EXECUTE FUNCTION app.set_updated_at();
CREATE TRIGGER password_history_updated_at BEFORE UPDATE ON public.password_history
  FOR EACH ROW EXECUTE FUNCTION app.set_updated_at();
CREATE TRIGGER user_tokens_updated_at BEFORE UPDATE ON public.user_tokens
  FOR EACH ROW EXECUTE FUNCTION app.set_updated_at();
CREATE TRIGGER roles_updated_at BEFORE UPDATE ON public.roles
  FOR EACH ROW EXECUTE FUNCTION app.set_updated_at();

-- ---------------------------------------------------------------------------------------------
-- organization_id of password_history and user_tokens is always the user's (Backend Schema
-- 4.3, 4.4). SECURITY INVOKER: the lookup runs under the caller's RLS, so a user of another
-- organization is not found, the copied value is NULL and the RLS check then rejects the row.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app.copy_user_organization() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  SELECT u.organization_id INTO NEW.organization_id FROM public.users u WHERE u.id = NEW.user_id;
  RETURN NEW;
END $$;

CREATE TRIGGER password_history_organization BEFORE INSERT OR UPDATE OF user_id, organization_id
  ON public.password_history FOR EACH ROW EXECUTE FUNCTION app.copy_user_organization();
CREATE TRIGGER user_tokens_organization BEFORE INSERT OR UPDATE OF user_id, organization_id
  ON public.user_tokens FOR EACH ROW EXECUTE FUNCTION app.copy_user_organization();

-- ---------------------------------------------------------------------------------------------
-- 11.3 Last Org Super Admin protection: an organization always keeps at least one active,
-- non-deleted Org Super Admin. Deferred to commit so a transaction may hand the role over.
-- Only fires when a row that counted (active, non-deleted super admin) stops counting.
-- An organization that is itself deleted (soft or hard) is exempt.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app.keep_one_super_admin() RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = pg_catalog, public
AS $$
BEGIN
  IF NOT (OLD.is_org_super_admin AND OLD.status = 'active' AND OLD.deleted_at IS NULL) THEN
    RETURN NULL;
  END IF;
  IF TG_OP = 'UPDATE'
     AND NEW.is_org_super_admin AND NEW.status = 'active' AND NEW.deleted_at IS NULL
     AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id THEN
    RETURN NULL;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organizations o
                 WHERE o.id = OLD.organization_id AND o.deleted_at IS NULL) THEN
    RETURN NULL;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.users u
                 WHERE u.organization_id = OLD.organization_id
                   AND u.is_org_super_admin AND u.status = 'active' AND u.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'LAST_SUPER_ADMIN' USING ERRCODE = 'P0001';
  END IF;
  RETURN NULL;
END $$;

CREATE CONSTRAINT TRIGGER users_keep_one_super_admin
  AFTER UPDATE OR DELETE ON public.users
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION app.keep_one_super_admin();

-- ---------------------------------------------------------------------------------------------
-- 11.6 app.create_default_roles(org): the four system roles with their default permissions
-- (Backend Schema 9.2). Called by the API in platform context right after creating an
-- organization; SECURITY DEFINER because the platform context cannot write tenant rows under
-- RLS. Idempotent. Permissions missing from the catalogue are skipped (the catalogue is seeded
-- in step 11). Platform default SMS templates are copied here from step 21 on.
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION app.create_default_roles(p_org_id uuid) RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = pg_catalog, public
AS $$
DECLARE
  observer_keys  text[] := ARRAY['event.view', 'turnout.view', 'results.view', 'reports.download',
                                 'audit.view.event', 'voter.view'];
  moderator_keys text[] := observer_keys || ARRAY['event.create', 'event.edit', 'event.publish',
                                 'event.close', 'event.cancel', 'category.manage',
                                 'contester.manage', 'voter.manage', 'messages.send',
                                 'code.regenerate', 'kiosk.operate', 'results.resolve_tie',
                                 'results.publish'];
  admin_keys     text[] := moderator_keys || ARRAY['staff.manage', 'assignments.manage',
                                 'org.settings.manage', 'audit.view.org', 'event.access_all',
                                 'event.activate', 'event.reopen', 'event.archive'];
  super_keys     text[] := admin_keys || ARRAY['roles.manage', 'admins.manage'];
BEGIN
  IF NOT app.is_platform_admin() THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = 'P0001';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM organizations WHERE id = p_org_id AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO roles (organization_id, name, description, system_key, is_system)
  VALUES
    (p_org_id, 'Org Super Admin', 'Account owner: every permission, manages roles', 'org_super_admin', true),
    (p_org_id, 'Admin', 'Manages staff, events and settings', 'admin', true),
    (p_org_id, 'Moderator', 'Runs the events they are mapped to', 'moderator', true),
    (p_org_id, 'Observer', 'Read-only access to mapped events', 'observer', true)
  ON CONFLICT (organization_id, system_key) DO NOTHING;

  INSERT INTO role_permissions (role_id, permission_key, organization_id)
  SELECT r.id, p.key, r.organization_id
  FROM roles r
  JOIN LATERAL unnest(CASE r.system_key
         WHEN 'org_super_admin' THEN super_keys
         WHEN 'admin' THEN admin_keys
         WHEN 'moderator' THEN moderator_keys
         ELSE observer_keys END) AS k(key) ON true
  JOIN permissions p ON p.key = k.key
  WHERE r.organization_id = p_org_id AND r.is_system
  ON CONFLICT (role_id, permission_key) DO NOTHING;
END $$;

-- ---------------------------------------------------------------------------------------------
-- Row level security (Backend Schema 10.2, 10.3). Enabled, not forced: vk_owner (migrations
-- and SECURITY DEFINER functions) is exempt and those functions filter by organization.
-- ---------------------------------------------------------------------------------------------

-- organizations: see and update your own; platform admins see, create and update all
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_select ON public.organizations FOR SELECT TO vk_api
  USING (id = app.current_org_id() OR app.is_platform_admin());
CREATE POLICY org_update ON public.organizations FOR UPDATE TO vk_api
  USING (id = app.current_org_id() OR app.is_platform_admin())
  WITH CHECK (id = app.current_org_id() OR app.is_platform_admin());
CREATE POLICY org_insert ON public.organizations FOR INSERT TO vk_api
  WITH CHECK (app.is_platform_admin());

-- users, password_history, user_tokens: organization_id may be NULL (platform admins)
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
CREATE POLICY users_tenant ON public.users FOR ALL TO vk_api
  USING (organization_id = app.current_org_id()
         OR (app.is_platform_admin() AND (organization_id IS NULL OR app.current_org_id() IS NULL
                                          OR organization_id = app.current_org_id())))
  WITH CHECK (organization_id = app.current_org_id() OR app.is_platform_admin());

ALTER TABLE public.password_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY password_history_tenant ON public.password_history FOR ALL TO vk_api
  USING (organization_id = app.current_org_id()
         OR (app.is_platform_admin() AND (organization_id IS NULL OR app.current_org_id() IS NULL
                                          OR organization_id = app.current_org_id())))
  WITH CHECK (organization_id = app.current_org_id() OR app.is_platform_admin());

ALTER TABLE public.user_tokens ENABLE ROW LEVEL SECURITY;
CREATE POLICY user_tokens_tenant ON public.user_tokens FOR ALL TO vk_api
  USING (organization_id = app.current_org_id()
         OR (app.is_platform_admin() AND (organization_id IS NULL OR app.current_org_id() IS NULL
                                          OR organization_id = app.current_org_id())))
  WITH CHECK (organization_id = app.current_org_id() OR app.is_platform_admin());

-- permissions: global catalogue, read-only for the API
ALTER TABLE public.permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY permissions_read ON public.permissions FOR SELECT TO vk_api USING (true);

-- Standard tenant template (10.2): roles, role_permissions, user_roles
ALTER TABLE public.roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_tenant ON public.roles FOR ALL TO vk_api
  USING (organization_id = app.current_org_id())
  WITH CHECK (organization_id = app.current_org_id());
CREATE POLICY roles_platform_read ON public.roles FOR SELECT TO vk_api
  USING (app.is_platform_admin());

ALTER TABLE public.role_permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY role_permissions_tenant ON public.role_permissions FOR ALL TO vk_api
  USING (organization_id = app.current_org_id())
  WITH CHECK (organization_id = app.current_org_id());
CREATE POLICY role_permissions_platform_read ON public.role_permissions FOR SELECT TO vk_api
  USING (app.is_platform_admin());

ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY user_roles_tenant ON public.user_roles FOR ALL TO vk_api
  USING (organization_id = app.current_org_id())
  WITH CHECK (organization_id = app.current_org_id());
CREATE POLICY user_roles_platform_read ON public.user_roles FOR SELECT TO vk_api
  USING (app.is_platform_admin());

-- ---------------------------------------------------------------------------------------------
-- Grants (Backend Schema 10.4). Tables created later in public get the same defaults; their
-- migrations still state their grants and RLS explicitly.
-- ---------------------------------------------------------------------------------------------
ALTER DEFAULT PRIVILEGES FOR ROLE vk_owner IN SCHEMA public
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO vk_api;
ALTER DEFAULT PRIVILEGES FOR ROLE vk_owner IN SCHEMA public
  GRANT SELECT ON TABLES TO vk_readonly;
ALTER DEFAULT PRIVILEGES FOR ROLE vk_owner IN SCHEMA public
  GRANT USAGE, SELECT ON SEQUENCES TO vk_api;

GRANT SELECT, INSERT, UPDATE, DELETE ON
  public.organizations, public.users, public.password_history, public.user_tokens,
  public.roles, public.role_permissions, public.user_roles
  TO vk_api;
GRANT SELECT ON public.permissions TO vk_api;

-- Support role: everything except credentials (password and token hashes).
GRANT SELECT ON public.organizations, public.permissions, public.roles, public.role_permissions,
  public.user_roles TO vk_readonly;
GRANT SELECT (id, organization_id, email, email_normalized, full_name, phone, status,
              is_platform_admin, is_org_super_admin, language, theme_preference,
              failed_login_count, locked_until, last_login_at, password_changed_at,
              created_at, updated_at, deleted_at)
  ON public.users TO vk_readonly;
GRANT SELECT (id, user_id, organization_id, created_at, updated_at)
  ON public.password_history TO vk_readonly;
GRANT SELECT (id, user_id, organization_id, purpose, expires_at, used_at, created_by,
              created_at, updated_at)
  ON public.user_tokens TO vk_readonly;
